describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      // product without weight
      expect(calc.computeShippingCents([makeLine("a", 2)], 5000)).toBe(0);
    });

    it("selects first bracket when weight <= upToGrams", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    });

    it("selects middle bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 1000)], 5000)).toBe(700);
    });

    it("selects highest bracket at boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 5000)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 6000)], 5000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost when not set", () => {
      const calc2 = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 900 },
      ]);
      // weight = 3000 > 2000, overflow = last bracket = 900
      expect(calc2.computeShippingCents([makeLine("a", 1, 3000)], 5000)).toBe(900);
    });

    it("sums weight across multiple lines", () => {
      // 2 x 300g + 1 x 500g = 1100g → second bracket (up to 2000)
      const lines = [makeLine("a", 2, 300), makeLine("b", 1, 500)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("handles unsorted brackets (sorted internally)", () => {
      const calc3 = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(calc3.computeShippingCents([makeLine("a", 1, 400)], 5000)).toBe(300);
    });

    it("boundary: weight exactly at first bracket limit", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    });

    it("boundary: weight one gram over first bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 501)], 5000)).toBe(700);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects quantity <= 0", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity to a new value", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes the product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nope", 1)).toThrow(
        "Product nope is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals / pricing pipeline", () => {
    it("computes subtotal as sum of price * qty", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4500);
    });

    it("applies discount policy", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(productA, 3); // subtotal 3000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(discount.computeDiscountCents).toHaveBeenCalledWith(3000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(productA, 1); // subtotal 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(productA, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("tax is computed on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(productA, 2); // subtotal 2000, discount 500, discounted 1500
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    });

    it("shipping receives lines and discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
      const totals = cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(799);
    });

    it("total = discounted subtotal + tax + shipping", () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
      const tax: TaxCalculator = { computeTaxCents: () => 50 };
      const shipping: ShippingCalculator = { computeShippingCents: () => 200 };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal 1000
      const totals = cart.totals();
      // discounted = 1000-100 = 900, total = 900+50+200 = 1150
      expect(totals.totalCents).toBe(1150);
    });

    it("uses default region US", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
    });

    it("uses custom region", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
    });

    it("empty cart yields all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });
  });
});

