      expect(calc3.computeShippingCents([makeLine("a", 1, 400)], 5000)).toBe(300);
    });

    it("boundary: weight exactly at first bracket limit", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    });

    it("boundary: weight one gram over first bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 501)], 5000)).toBe(700);
    });
  });
});

