import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via PriceFetcher before computing totals", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-1),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        RangeError,
      );
    });

    it("propagates fetcher rejection", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("inventory checking", () => {
    it("passes when all items are available", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(checker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      const cart = new Cart();
      cart.add(productA, 3);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(3);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1,
        }),
      };
      const cart = new Cart();
      cart.add(productA, 5);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(1);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "b is out" }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        expect((e as InventoryError).productId).toBe("b");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider when supplied", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.taxCents).toBe(80); // 10% of 800
    });

    it("propagates async tax provider error", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("composes price refresh + inventory + async tax + discount + shipping", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(300),
      });
      cart.add(productA, 4);
      // refreshed price = 500, qty=4, subtotal = 2000
      // discount = 10% of 2000 = 200, discounted = 1800
      // tax = 8% of 1800 = 144
      // shipping = 300
      // total = 1800 + 144 + 300 = 2244
      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(144);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(2244);
    });

    it("checkout without collaborators returns sync totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("returns refreshed lines in result", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(9999);
    });
  });
});
"}

