toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  qty: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 1)], 2000)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal >= freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
      expect(calc.computeShippingCents([makeLine("a", 1)], 6000)).toBe(0);
    });

    it("charges when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 4999)).toBe(799);
    });

    it("freeOverCents=0 means always free for non-empty", () => {
      const calc = new FlatShippingCalculator(799, 0);
      expect(calc.computeShippingCents([makeLine("a", 1)], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      // product without weight
      expect(calc.computeShippingCents([makeLine("a", 2)], 5000)).toBe(0);
    });

    it("selects first bracket when weight <= upToGrams", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    });

    it("selects middle bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 1000)], 5000)).toBe(700);
    });

    it("selects highest bracket at boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 5000)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 6000)], 5000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost when not set", () => {
      const calc2 = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 900 },
      ]);
      // weight = 3000 > 2000, overflow = last bracket = 900
      expect(calc2.computeShippingCents([makeLine("a", 1, 3000)], 5000)).toBe(900);
    });

    it("sums weight across multiple lines", () => {
      // 2 x 300g + 1 x 500g = 1100g → second bracket (up to 2000)
      const lines = [makeLine("a", 2, 300), makeLine("b", 1, 500)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("handles unsorted brackets (sorted internally)", () => {
      const calc3 = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(calc3.computeShippingCents([makeLine("a", 1, 400)], 5000)).toBe(300);
    });

    it("boundary: weight exactly at first bracket limit", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    });

    it("boundary: weight one gram over first bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 1, 501)], 5000)).toBe(700);
    });
  });
});

